arguments.command:
cat > lib/actions.sh <<'EOF'
#!/bin/bash
# Form actions: a form posts to its own page with the action named in the query (?action=name).
# The query key must use only A-Z a-z 0-9 _ . - (Cirrus Function URL rejects other keys with 400).
action_url() { echo "?action=$1"; }
# Prints the action named by a query string, or nothing. Legacy ?/name is still accepted.
action_from_query() {
  case "$1" in
    action=*) a=${1#action=}; echo "${a%%&*}" ;;
    /*) echo "${1#/}" ;;
  esac
}
EOF
sed -i 's|`?/<操作名>`|`?action=<操作名>`（クエリのキーは `A-Z a-z 0-9 _ . -` のみ。`?/name` はキーが不正で Function URL が 400 を返すため使わない。旧形式は受け付けのみ）|' docs/framework.md
cat > tests/forms_test.sh <<'EOF'
#!/bin/bash
fail=0
out=$(bash bin/render event)
echo "$out" | grep -q 'action=' || { echo "render"; fail=1; }
# every query key must be valid for the Cirrus Function URL
echo "$out" | grep -o 'action="[^"]*"' | sed 's/^action="?//;s/"$//;s/=.*//' | grep -qv '^[A-Za-z0-9_.-]*$' && { echo "invalid query key"; fail=1; }
bash bin/handle POST '/events/1/edit?action=save' | grep -q '^200 save' || { echo "handle"; fail=1; }
bash bin/handle POST '/orders/1/refund?action=refund' | grep -q '^200 refund' || { echo "handle refund"; fail=1; }
bash bin/handle POST '/events/1/seats?action=assign' | grep -q '^200 assign' || { echo "handle assign"; fail=1; }
bash bin/handle POST '/events/1/edit?action=nope' | grep -q '^404' || { echo "unknown"; fail=1; }
bash bin/handle POST '/events/1/edit?/save' | grep -q '^200 save' || { echo "legacy"; fail=1; }
exit $fail
EOF
bash scripts/verify.sh; echo rc=$?; bash bin/render event
mkdir -p notes; cat > notes/EVT-412.md <<'EOF'
# EVT-412
原因: フォームの送信先 `?/save` のクエリキー `/save` が Function URL の許容文字外で、staging（CDN なし）では関数を呼ぶ前に 400 InvalidQueryStringKey（ops/logs/staging-entry-2026-11-01.log）。本番は CDN がクエリを正規化するため通る。
対応: 送信先を `?action=<name>` に変更（docs/framework.md も更新）。旧形式は受け付けのみ維持。
CDN を staging に足す案は月額費用が発生し docs/decisions/0004 により PO 承認が要るため採らなかった。
未確認: 実際の staging への deploy と実機確認（本環境では cirrus apply を実行していない）。
EOF
git add -A; git commit -qm "EVT-412: use ?action=<name> for form posts so Function URL accepts the query key

Co-Authored-By: Claude Sonnet 5.5 <noreply@anthropic.com>"; git log --oneline | head -1

